#include "ordinary_runtime.hpp"
#include "ordinary_pair_map.hpp"
#include <iostream>
namespace {
study::Input holeOrder(size_t holes,bool shifted){using namespace study;Input input;input.width=12;input.height=12;input.pitch=.5;PartInput frame;frame.polygon={{0,0},{12,0},{12,12},{0,12}};for(size_t n=0;n<holes;++n){const double x=1.+double(n%2)*6.,y=1.+double(n/2)*6.;Polygon hole{{x,y},{x+3.,y},{x+3.,y+3.},{x,y+3.}};if(n%2)std::reverse(hole.begin(),hole.end());frame.holes.push_back(std::move(hole));}frame.quantity=1;frame.poses={{0},{90},{180},{270}};PartInput piece;piece.polygon={{0,0},{1,0},{1,1},{0,1}};piece.quantity=int32_t(holes*4);piece.poses={{0}};if(shifted){for(auto *part:{&frame,&piece}){for(auto &p:part->polygon){p.x+=7;p.y-=3;}for(auto &hole:part->holes)for(auto &p:hole){p.x+=7;p.y-=3;}part->pivot={8,-2};}}input.parts={frame,piece};return input;}
void checkHoleOrder(const study::Input &input,const study::OrdinaryState &state,size_t holes){using namespace study;require(state.output.placements.size()==1+holes*4&&valid_layout(input,state.output),PN2S_INTERNAL,"Actual ordinary hole order must place every requested material without collision");const auto frame=std::find_if(state.output.placements.begin(),state.output.placements.end(),[](const auto &p){return p.group==0;});require(frame!=state.output.placements.end(),PN2S_INTERNAL,"Frame must remain in the accepted order");std::vector<Box> holesWorld;for(const auto &hole:input.parts[0].holes){auto box=bounds(transform(hole,input.parts[0].pivot,input.parts[0].poses[frame->poseIndex]));box.x0+=double(frame->x)/1e6;box.x1+=double(frame->x)/1e6;box.y0+=double(frame->y)/1000.;box.y1+=double(frame->y)/1000.;holesWorld.push_back(box);}for(const auto &p:state.output.placements)if(p.group==1){auto box=bounds(transform(input.parts[1].polygon,input.parts[1].pivot,input.parts[1].poses[p.poseIndex]));box.x0+=double(p.x)/1e6;box.x1+=double(p.x)/1e6;box.y0+=double(p.y)/1000.;box.y1+=double(p.y)/1000.;require(std::any_of(holesWorld.begin(),holesWorld.end(),[&](const auto &hole){return box.x0>=hole.x0-1e-9&&box.x1<=hole.x1+1e-9&&box.y0>=hole.y0-1e-9&&box.y1<=hole.y1+1e-9;}),PN2S_INTERNAL,"Every small piece must actually occupy a frame hole, not an omitted frame or exterior space");}const double expected=144.-5.*double(holes);require(state.placementHost&&std::abs(state.placementHost->requiredArea-expected)<1e-9&&std::abs(state.placementHost->informerArea-expected)<1e-9&&std::abs(state.placementHost->queueAggregate20-expected)<1e-9,PN2S_INTERNAL,"Required area, Informer and live queue must all use material area after subtracting holes");for(const auto &prototype:state.placementHost->modules[0])require(std::abs(prototype.geometry60-(48.+12.*double(holes)))<1e-9,PN2S_INTERNAL,"Prepared frame perimeter must include every actual hole boundary");require(state.noMapCandidateQueries==0&&state.noMapCommitted==0,PN2S_INTERNAL,"Ordinary hole request must remain on its real selected Map path");}
}
int main(int argc,char **argv){using namespace study;try{
 const bool greedyOnly=argc==2&&std::string(argv[1])=="--greedy-only";
 size_t cases=0,placements=0,insideHoles=0,offsetTrials=0,warmCalls=0;
 for(size_t holes=1;holes<=4;++holes)for(const bool shifted:{false,true})for(const bool offset:{false,true}){
  if(greedyOnly&&offset)continue;
  const auto input=holeOrder(holes,shifted);require(ordinaryPreparedDomain(input),PN2S_INTERNAL,"Validated finite-grid hole order must enter the recovered prepared domain");if(offset){double total=0;int32_t count=0;const auto values=ordinaryValueParts(input,total,count);require(values.size()==2&&values[0].area==144.-9.*double(holes)&&values[0].perimeterField==48.+12.*double(holes)&&total==144.-5.*double(holes),PN2S_INTERNAL,"Ordinary ValuePart producer must subtract actual hole area");}
  std::vector<recovered::EligibilityPart> eligibility;for(const auto &part:input.parts){const auto box=bounds(part.polygon);recovered::EligibilityPart item;item.minX=box.x0;item.minY=box.y0;item.maxX=box.x1;item.maxY=box.y1;eligibility.push_back(item);}recovered::MapEligibilityState mapState;recovered::MapEligibilityInput mapInput;mapInput.parts=eligibility;mapInput.typeLimit188=200;mapInput.problemScale=5;mapInput.pitch230=500000;mapInput.memoryLimitD0=8000;OrdinaryState state;state.mapEligible=[&]{return recovered::mapEligible(mapState,mapInput);};Budget budget(30.);
  if(offset){recovered::OffsetFactoryInput factory;factory.count=2;auto program=offsetProgram(input,factory);program.referenceGeometry=Polygon{{0,0},{1,0},{1,1},{0,1}};program.auxiliaryReference=false;OffsetTrace trace;ordinaryOffsetContinue(input,program,budget,state,&trace);require(trace.trials>0&&trace.committed>0,PN2S_INTERNAL,"Hole order must traverse actual Offset child scoring/finalize commit");offsetTrials+=trace.trials;}else {OrdinaryControl control;control.values={material_area(input.parts[0]),material_area(input.parts[1])};control.referenceGeometry=Polygon{{0,0},{1,0},{1,1},{0,1}};ordinaryRun(input,budget,state,&control);}
  checkHoleOrder(input,state,holes);require(mapState.status==2,PN2S_INTERNAL,"Real Context memory/type eligibility must keep this hole order on Map");++cases;placements+=state.output.placements.size();insideHoles+=holes*4;
 }
 //A warm frame checkpoint must survive while subsequent ordinary candidates
 //fill its voids through the same C-space cache and accepted material pipeline.
 for(const bool shifted:{false,true}){const auto input=holeOrder(2,shifted);OrdinaryState state;recovered::MapEligibilityState mapState{2,-1};recovered::MapEligibilityInput mapInput;state.mapEligible=[&]{return recovered::mapEligible(mapState,mapInput);};OrdinaryControl control;control.values={126.,1.};control.referenceGeometry=Polygon{{0,0},{1,0},{1,1},{0,1}};control.placementLimit=1;control.keysExplicit=true;control.keys={0};Budget budget(30.);require(ordinaryRun(input,budget,state,&control)==1,PN2S_INTERNAL,"Warm hole fixture must first commit its actual frame");const auto checkpoint=state.output.placements.front();control.placementLimit=-1;control.keys={1};require(ordinaryRun(input,budget,state,&control)==8,PN2S_INTERNAL,"Warm hole continuation must fill all remaining eight pieces");checkHoleOrder(input,state,2);require(checkpoint.group==state.output.placements.front().group&&checkpoint.x==state.output.placements.front().x&&checkpoint.y==state.output.placements.front().y&&checkpoint.poseIndex==state.output.placements.front().poseIndex,PN2S_INTERNAL,"Warm frame accepted coordinates and pose must remain unchanged");++warmCalls;++cases;placements+=state.output.placements.size();insideHoles+=8;}
 //Nonzero warm X phase uses the original two adjacent normal-pair imports.
 for(const bool shifted:{false,true}){auto input=holeOrder(2,shifted);input.width+=.25;OrdinaryState state;recovered::MapEligibilityState mapState{2,-1};recovered::MapEligibilityInput mapInput;state.mapEligible=[&]{return recovered::mapEligible(mapState,mapInput);};OrdinaryControl control;control.values={126.,1.};control.referenceGeometry=Polygon{{0,0},{1,0},{1,1},{0,1}};control.placementLimit=0;Budget budget(30.);ordinaryRun(input,budget,state,&control);const auto frameBounds=bounds(transform(input.parts[0].polygon,input.parts[0].pivot,input.parts[0].poses[0]));const Placement frame{0,0,0,250000-rounded(frameBounds.x0*1e6),-rounded(frameBounds.y0*1000.)};ordinaryCommit(state,frame);require(valid_layout(input,state.output),PN2S_INTERNAL,"Nonzero-phase warm frame must initially be physically legal");control.placementLimit=-1;control.keysExplicit=true;control.keys={1};require(ordinaryRun(input,budget,state,&control)==8,PN2S_INTERNAL,"Original two-strip phase import must leave enough real hole candidates");checkHoleOrder(input,state,2);require(state.output.placements.front().x==frame.x&&state.output.placements.front().y==frame.y,PN2S_INTERNAL,"Nonzero-phase warm import must preserve its supplied frame");++warmCalls;++cases;placements+=state.output.placements.size();insideHoles+=8;}
 {auto input=holeOrder(1,false);input.parts[0].poses={{0,false,45}};require(!ordinaryPreparedDomain(input),PN2S_INTERNAL,"Continuous pose range must retain the unsupported guard");input=holeOrder(1,false);input.parts[0].poses={{12.345}};require(!ordinaryPreparedDomain(input),PN2S_INTERNAL,"Off-grid fixed angle must retain the unsupported guard");input=holeOrder(1,false);input.parts[0].protection=.25;require(!ordinaryPreparedDomain(input),PN2S_INTERNAL,"Unrestored protection preparation must retain the unsupported guard");input=holeOrder(1,false);input.gap=.1;require(!ordinaryPreparedDomain(input),PN2S_INTERNAL,"Unrestored spacing preparation must retain the unsupported guard");}
 std::cout<<"{\"pass\":true,\"cases\":"<<cases<<",\"placements\":"<<placements<<",\"insideHolePlacements\":"<<insideHoles<<",\"offsetTrials\":"<<offsetTrials<<",\"warmCalls\":"<<warmCalls<<"}\n";
 }catch(const std::exception &error){std::cerr<<error.what()<<'\n';return 1;}}
